#ifdef CONFIG_BOOTARGS
	extern int main(int argc, char **argv);
	extern char **sys_boot_prepare_main_args(int *argc);

	int argc = 0;
	char **argv = sys_boot_prepare_main_args(&argc);
	(void)main(argc, argv);
#else
	extern int main(void);

	(void)main();
#endif /* CONFIG_BOOTARGS */

