void z_thread_suspend_current(struct k_thread *thread)
{
	k_spinlock_key_t key = z_sched_spinlock_lock();

	z_mark_thread_as_suspended(thread);
	z_metairq_preempted_clear(thread);
	dequeue_thread(thread);
	update_cache(1);
	z_swap_locked(key);
}

